// Bundles the SQL migrations generated by drizzle-kit into a single TypeScript
// module that can be imported in the browser, where there is no filesystem.
//
// drizzle-kit writes .sql files + meta/_journal.json to db/migrations. PGlite
// (running in the browser) can't read those at runtime, so we inline them here.
// Run via `pnpm db:generate` (which runs `drizzle-kit generate` first).
import { readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const MIGRATIONS_DIR = "db/migrations"
const OUTPUT = "db/migrations.generated.ts"

const journal = JSON.parse(
  readFileSync(join(MIGRATIONS_DIR, "meta", "_journal.json"), "utf8"),
)

const migrations = [...journal.entries]
  .sort((a, b) => a.idx - b.idx)
  .map((entry) => ({
    tag: entry.tag,
    sql: readFileSync(join(MIGRATIONS_DIR, `${entry.tag}.sql`), "utf8"),
  }))

const file =
  "// AUTO-GENERATED by scripts/build-migrations.mjs — do not edit by hand.\n" +
  "// Regenerate with `pnpm db:generate` after changing db/schema.ts.\n\n" +
  "export type BundledMigration = { tag: string; sql: string }\n\n" +
  "export const migrations: BundledMigration[] = [\n" +
  migrations
    .map((m) => `  { tag: ${JSON.stringify(m.tag)}, sql: ${JSON.stringify(m.sql)} },`)
    .join("\n") +
  "\n]\n"

writeFileSync(OUTPUT, file)
console.log(`Bundled ${migrations.length} migration(s) → ${OUTPUT}`)
